1  import {Str} from 'expensify-common';
     2  import lodashMapValues from 'lodash/mapValues';
     3  import lodashSortBy from 'lodash/sortBy';
     4  import type {ForwardedRef} from 'react';
     5  import React, {forwardRef, useCallback, useEffect, useImperativeHandle, useMemo, useRef, useState} from 'react';
     6  import type {OnyxCollection} from 'react-native-onyx';
     7  import {useOnyx} from 'react-native-onyx';
     8  import * as Expensicons from '@components/Icon/Expensicons';
     9  import type {Mention} from '@components/MentionSuggestions';
    10  import MentionSuggestions from '@components/MentionSuggestions';
    11  import {usePersonalDetails} from '@components/OnyxProvider';
    12  import useArrowKeyFocusManager from '@hooks/useArrowKeyFocusManager';
    13  import useCurrentReportID from '@hooks/useCurrentReportID';
    14  import useCurrentUserPersonalDetails from '@hooks/useCurrentUserPersonalDetails';
    15  import useDebounce from '@hooks/useDebounce';
    16  import useLocalize from '@hooks/useLocalize';
    17  import localeCompare from '@libs/LocaleCompare';
    18  import * as LoginUtils from '@libs/LoginUtils';
    19  import * as PersonalDetailsUtils from '@libs/PersonalDetailsUtils';
    20  import getPolicyEmployeeAccountIDs from '@libs/PolicyEmployeeListUtils';
    21  import * as ReportUtils from '@libs/ReportUtils';
    22  import * as SuggestionsUtils from '@libs/SuggestionUtils';
    23  import {isValidRoomName} from '@libs/ValidationUtils';
    24  import * as ReportUserActions from '@userActions/Report';
    25  import CONST from '@src/CONST';
    26  import ONYXKEYS from '@src/ONYXKEYS';
    27  import type {PersonalDetails, PersonalDetailsList, Report} from '@src/types/onyx';
    28  import type {SuggestionsRef} from './ReportActionCompose';
    29  import type {SuggestionProps} from './Suggestions';
    30
    31  type SuggestionValues = {
    32      suggestedMentions: Mention[];
    33      atSignIndex: number;
    34      shouldShowSuggestionMenu: boolean;
    35      mentionPrefix: string;
    36      prefixType: string;
    37  };
    38
    39  /**
    40   * Check if this piece of string looks like a mention
    41   */
    42  const isMentionCode = (str: string): boolean => CONST.REGEX.HAS_AT_MOST_TWO_AT_SIGNS.test(str);
    43
    44  const defaultSuggestionsValues: SuggestionValues = {
    45      suggestedMentions: [],
    46      atSignIndex: -1,
    47      shouldShowSuggestionMenu: false,
    48      mentionPrefix: '',
    49      prefixType: '',
    50  };
    51
    52  type SuggestionPersonalDetailsList = Record<
    53      string,
    54      | (PersonalDetails & {
    55            weight: number;
    56        })
    57      | null
    58  >;
    59
    60  function getDisplayName(details: PersonalDetails) {
    61      const displayNameFromAccountID = ReportUtils.getDisplayNameForParticipant(details.accountID);
    62      if (!displayNameFromAccountID) {
    63          return details.login?.length ? details.login : '';
    64      }
    65      return displayNameFromAccountID;
    66  }
    67
    68  /**
    69   * Comparison function to sort users. It compares weights, display names, and accountIDs in that order
    70   */
    71  function compareUserInList(first: PersonalDetails & {weight: number}, second: PersonalDetails & {weight: number}) {
    72      if (first.weight !== second.weight) {
    73          return first.weight - second.weight;
    74      }
    75
    76      const displayNameLoginOrder = localeCompare(getDisplayName(first), getDisplayName(second));
    77      if (displayNameLoginOrder !== 0) {
    78          return displayNameLoginOrder;
    79      }
    80
    81      return first.accountID - second.accountID;
    82  }
    83
    84  function SuggestionMention(
    85      {value, selection, setSelection, updateComment, isAutoSuggestionPickerLarge, measureParentContainerAndReportCursor, isComposerFocused, isGroupPolicyReport, policyID}: SuggestionProps,
    86      ref: ForwardedRef<SuggestionsRef>,
    87  ) {
    88      const personalDetails = usePersonalDetails() ?? CONST.EMPTY_OBJECT;
    89      const {translate, formatPhoneNumber} = useLocalize();
    90      const [suggestionValues, setSuggestionValues] = useState(defaultSuggestionsValues);
    91      const suggestionValuesRef = useRef(suggestionValues);
    92      suggestionValuesRef.current = suggestionValues;
    93
    94      const [reports] = useOnyx(ONYXKEYS.COLLECTION.REPORT);
    95
    96      const currentUserPersonalDetails = useCurrentUserPersonalDetails();
    97      const isMentionSuggestionsMenuVisible = !!suggestionValues.suggestedMentions.length && suggestionValues.shouldShowSuggestionMenu;
    98
    99      const currentReportID = useCurrentReportID();
   100      const currentReport = reports?.[`${ONYXKEYS.COLLECTION.REPORT}${currentReportID?.currentReportID}`];
   101      // Smaller weight means higher order in suggestion list
   102      const getPersonalDetailsWeight = useCallback(
   103          (detail: PersonalDetails, policyEmployeeAccountIDs: number[]): number => {
   104              if (ReportUtils.isReportParticipant(detail.accountID, currentReport)) {
   105                  return 0;
   106              }
   107              if (policyEmployeeAccountIDs.includes(detail.accountID)) {
   108                  return 1;
   109              }
   110              return 2;
   111          },
   112          [currentReport],
   113      );
   114      const weightedPersonalDetails: PersonalDetailsList | SuggestionPersonalDetailsList = useMemo(() => {
   115          const policyEmployeeAccountIDs = getPolicyEmployeeAccountIDs(policyID);
   116          if (!ReportUtils.isGroupChat(currentReport) && !ReportUtils.doesReportBelongToWorkspace(currentReport, policyEmployeeAccountIDs, policyID)) {
   117              return personalDetails;
   118          }
   119          return lodashMapValues(personalDetails, (detail) =>
   120              detail
   121                  ? {
   122                        ...detail,
   123                        weight: getPersonalDetailsWeight(detail, policyEmployeeAccountIDs),
   124                    }
   125                  : null,
   126          );
   127      }, [policyID, currentReport, personalDetails, getPersonalDetailsWeight]);
   128
   129      const [highlightedMentionIndex, setHighlightedMentionIndex] = useArrowKeyFocusManager({
   130          isActive: isMentionSuggestionsMenuVisible,
   131          maxIndex: suggestionValues.suggestedMentions.length - 1,
   132          shouldExcludeTextAreaNodes: false,
   133      });
   134
   135      // Used to store the selection index of the last inserted mention
   136      const suggestionInsertionIndexRef = useRef<number | null>(null);
   137
   138      // Used to detect if the selection has changed since the last suggestion insertion
   139      // If so, we reset the suggestionInsertionIndexRef
   140      const hasSelectionChanged = !(selection.end === selection.start && selection.start === suggestionInsertionIndexRef.current);
   141      if (hasSelectionChanged) {
   142          suggestionInsertionIndexRef.current = null;
   143      }
   144
   145      // Used to decide whether to block the suggestions list from showing to prevent flickering
   146      const shouldBlockCalc = useRef(false);
   147
   148      /**
   149       * Search for reports suggestions in server.
   150       *
   151       * The function is debounced to not perform requests on every keystroke.
   152       */
   153      const debouncedSearchInServer = useDebounce(
   154          useCallback(() => {
   155              const foundSuggestionsCount = suggestionValues.suggestedMentions.length;
   156              if (suggestionValues.prefixType === '#' && foundSuggestionsCount < 5 && isGroupPolicyReport) {
   157                  ReportUserActions.searchInServer(value, policyID);
   158              }
   159          }, [suggestionValues.suggestedMentions.length, suggestionValues.prefixType, policyID, value, isGroupPolicyReport]),
   160          CONST.TIMING.SEARCH_OPTION_LIST_DEBOUNCE_TIME,
   161      );
   162
   163      const formatLoginPrivateDomain = useCallback(
   164          (displayText = '', userLogin = '') => {
   165              if (userLogin !== displayText) {
   166                  return displayText;
   167              }
   168              // If the emails are not in the same private domain, we also return the displayText
   169              if (!LoginUtils.areEmailsFromSamePrivateDomain(displayText, currentUserPersonalDetails.login ?? '')) {
   170                  return Str.removeSMSDomain(displayText);
   171              }
   172
   173              // Otherwise, the emails must be of the same private domain, so we should remove the domain part
   174              return displayText.split('@')[0];
   175          },
   176          [currentUserPersonalDetails.login],
   177      );
   178
   179      const getMentionCode = useCallback(
   180          (mention: Mention, mentionType: string): string => {
   181              if (mentionType === '#') {
   182                  // room mention case
   183                  return mention.handle ?? '';
   184              }
   185              return mention.text === CONST.AUTO_COMPLETE_SUGGESTER.HERE_TEXT ? CONST.AUTO_COMPLETE_SUGGESTER.HERE_TEXT : `@${formatLoginPrivateDomain(mention.handle, mention.handle)}`;
   186          },
   187          [formatLoginPrivateDomain],
   188      );
   189
   190      /**
   191       * Replace the code of mention and update selection
   192       */
   193      const insertSelectedMention = useCallback(
   194          (highlightedMentionIndexInner: number) => {
   195              const commentBeforeAtSign = value.slice(0, suggestionValues.atSignIndex);
   196              const mentionObject = suggestionValues.suggestedMentions[highlightedMentionIndexInner];
   197              const mentionCode = getMentionCode(mentionObject, suggestionValues.prefixType);
   198              const commentAfterMention = value.slice(suggestionValues.atSignIndex + suggestionValues.mentionPrefix.length + 1);
   199
   200              updateComment(`${commentBeforeAtSign}${mentionCode} ${SuggestionsUtils.trimLeadingSpace(commentAfterMention)}`, true);
   201              const selectionPosition = suggestionValues.atSignIndex + mentionCode.length + CONST.SPACE_LENGTH;
   202              setSelection({
   203                  start: selectionPosition,
   204                  end: selectionPosition,
   205              });
   206              suggestionInsertionIndexRef.current = selectionPosition;
   207              setSuggestionValues((prevState) => ({
   208                  ...prevState,
   209                  suggestedMentions: [],
   210                  shouldShowSuggestionMenu: false,
   211              }));
   212          },
   213          [
   214              value,
   215              suggestionValues.atSignIndex,
   216              suggestionValues.suggestedMentions,
   217              suggestionValues.prefixType,
   218              suggestionValues.mentionPrefix.length,
   219              getMentionCode,
   220              updateComment,
   221              setSelection,
   222          ],
   223      );
   224
   225      /**
   226       * Clean data related to suggestions
   227       */
   228      const resetSuggestions = useCallback(() => {
   229          setSuggestionValues(defaultSuggestionsValues);
   230      }, []);
   231
   232      /**
   233       * Listens for keyboard shortcuts and applies the action
   234       */
   235      const triggerHotkeyActions = useCallback(
   236          (event: KeyboardEvent) => {
   237              const suggestionsExist = suggestionValues.suggestedMentions.length > 0;
   238
   239              if (((!event.shiftKey && event.key === CONST.KEYBOARD_SHORTCUTS.ENTER.shortcutKey) || event.key === CONST.KEYBOARD_SHORTCUTS.TAB.shortcutKey) && suggestionsExist) {
   240                  event.preventDefault();
   241                  if (suggestionValues.suggestedMentions.length > 0) {
   242                      insertSelectedMention(highlightedMentionIndex);
   243                      return true;
   244                  }
   245              }
   246
   247              if (event.key === CONST.KEYBOARD_SHORTCUTS.ESCAPE.shortcutKey) {
   248                  event.preventDefault();
   249
   250                  if (suggestionsExist) {
   251                      resetSuggestions();
   252                  }
   253
   254                  return true;
   255              }
   256          },
   257          [highlightedMentionIndex, insertSelectedMention, resetSuggestions, suggestionValues.suggestedMentions.length],
   258      );
   259
   260      const getUserMentionOptions = useCallback(
   261          (personalDetailsParam: PersonalDetailsList | SuggestionPersonalDetailsList, searchValue = ''): Mention[] => {
   262              const suggestions = [];
   263
   264              if (CONST.AUTO_COMPLETE_SUGGESTER.HERE_TEXT.includes(searchValue.toLowerCase())) {
   265                  suggestions.push({
   266                      text: CONST.AUTO_COMPLETE_SUGGESTER.HERE_TEXT,
   267                      alternateText: translate('mentionSuggestions.hereAlternateText'),
   268                      icons: [
   269                          {
   270                              source: Expensicons.Megaphone,
   271                              type: CONST.ICON_TYPE_AVATAR,
   272                          },
   273                      ],
   274                  });
   275              }
   276
   277              const filteredPersonalDetails = Object.values(personalDetailsParam ?? {}).filter((detail) => {
   278                  // If we don't have user's primary login, that member is not known to the current user and hence we do not allow them to be mentioned
   279                  if (!detail?.login || detail.isOptimisticPersonalDetail) {
   280                      return false;
   281                  }
   282                  // We don't want to mention system emails like notifications@expensify.com
   283                  if (CONST.RESTRICTED_EMAILS.includes(detail.login) || CONST.RESTRICTED_ACCOUNT_IDS.includes(detail.accountID)) {
   284                      return false;
   285                  }
   286                  const displayName = PersonalDetailsUtils.getDisplayNameOrDefault(detail);
   287                  const displayText = displayName === formatPhoneNumber(detail.login) ? displayName : `${displayName} ${detail.login}`;
   288                  if (searchValue && !displayText.toLowerCase().includes(searchValue.toLowerCase())) {
   289                      return false;
   290                  }
   291
   292                  // Given the mention is inserted by user, we don't want to show the mention options unless the
   293                  // selection index changes. In that case, suggestionInsertionIndexRef.current will be null.
   294                  // See https://github.com/Expensify/App/issues/38358 for more context
   295                  if (suggestionInsertionIndexRef.current) {
   296                      return false;
   297                  }
   298
   299                  return true;
   300              }) as Array<PersonalDetails & {weight: number}>;
   301
   302              // At this point we are sure that the details are not null, since empty user details have been filtered in the previous step
   303              const sortedPersonalDetails = filteredPersonalDetails.sort(compareUserInList);
   304
   305              sortedPersonalDetails.slice(0, CONST.AUTO_COMPLETE_SUGGESTER.MAX_AMOUNT_OF_SUGGESTIONS - suggestions.length).forEach((detail) => {
   306                  suggestions.push({
   307                      text: formatLoginPrivateDomain(PersonalDetailsUtils.getDisplayNameOrDefault(detail), detail?.login),
   308                      alternateText: `@${formatLoginPrivateDomain(detail?.login, detail?.login)}`,
   309                      handle: detail?.login,
   310                      icons: [
   311                          {
   312                              name: detail?.login,
   313                              source: detail?.avatar ?? Expensicons.FallbackAvatar,
   314                              type: CONST.ICON_TYPE_AVATAR,
   315                              fallbackIcon: detail?.fallbackIcon,
   316                              id: detail?.accountID,
   317                          },
   318                      ],
   319                  });
   320              });
   321
   322              return suggestions;
   323          },
   324          [translate, formatPhoneNumber, formatLoginPrivateDomain],
   325      );
   326
   327      const getRoomMentionOptions = useCallback(
   328          (searchTerm: string, reportBatch: OnyxCollection<Report>): Mention[] => {
   329              const filteredRoomMentions: Mention[] = [];
   330              Object.values(reportBatch ?? {}).forEach((report) => {
   331                  if (!ReportUtils.canReportBeMentionedWithinPolicy(report, policyID ?? '-1')) {
   332                      return;
   333                  }
   334                  if (report?.reportName?.toLowerCase().includes(searchTerm.toLowerCase())) {
   335                      filteredRoomMentions.push({
   336                          text: report.reportName,
   337                          handle: report.reportName,
   338                          alternateText: report.reportName,
   339                      });
   340                  }
   341              });
   342
   343              return lodashSortBy(filteredRoomMentions, 'handle').slice(0, CONST.AUTO_COMPLETE_SUGGESTER.MAX_AMOUNT_OF_SUGGESTIONS);
   344          },
   345          [policyID],
   346      );
   347
   348      const calculateMentionSuggestion = useCallback(
   349          (newValue: string, selectionStart?: number, selectionEnd?: number) => {
   350              if (selectionEnd !== selectionStart || !selectionEnd || shouldBlockCalc.current || selectionEnd < 1 || !isComposerFocused) {
   351                  shouldBlockCalc.current = false;
   352                  resetSuggestions();
   353                  return;
   354              }
   355
   356              const afterLastBreakLineIndex = newValue.lastIndexOf('\n', selectionEnd - 1) + 1;
   357              const leftString = newValue.substring(afterLastBreakLineIndex, selectionEnd);
   358              const words = leftString.split(CONST.REGEX.SPACE_OR_EMOJI);
   359              const lastWord: string = words.at(-1) ?? '';
   360              const secondToLastWord = words[words.length - 3];
   361
   362              let atSignIndex: number | undefined;
   363              let suggestionWord = '';
   364              let prefix: string;
   365              let prefixType = '';
   366
   367              // Detect if the last two words contain a mention (two words are needed to detect a mention with a space in it)
   368              if (lastWord.startsWith('@') || lastWord.startsWith('#')) {
   369                  atSignIndex = leftString.lastIndexOf(lastWord) + afterLastBreakLineIndex;
   370                  suggestionWord = lastWord;
   371
   372                  prefix = suggestionWord.substring(1);
   373                  prefixType = suggestionWord.substring(0, 1);
   374              } else if (secondToLastWord && secondToLastWord.startsWith('@') && secondToLastWord.length > 1) {
   375                  atSignIndex = leftString.lastIndexOf(secondToLastWord) + afterLastBreakLineIndex;
   376                  suggestionWord = `${secondToLastWord} ${lastWord}`;
   377
   378                  prefix = suggestionWord.substring(1);
   379                  prefixType = suggestionWord.substring(0, 1);
   380              } else {
   381                  prefix = lastWord.substring(1);
   382              }
   383
   384              const nextState: Partial<SuggestionValues> = {
   385                  suggestedMentions: [],
   386                  atSignIndex,
   387                  mentionPrefix: prefix,
   388                  prefixType,
   389              };
   390
   391              if (isMentionCode(suggestionWord) && prefixType === '@') {
   392                  const suggestions = getUserMentionOptions(weightedPersonalDetails, prefix);
   393                  nextState.suggestedMentions = suggestions;
   394                  nextState.shouldShowSuggestionMenu = !!suggestions.length;
   395              }
   396
   397              const shouldDisplayRoomMentionsSuggestions = isGroupPolicyReport && (isValidRoomName(suggestionWord.toLowerCase()) || prefix === '');
   398              if (prefixType === '#' && shouldDisplayRoomMentionsSuggestions) {
   399                  // Filter reports by room name and current policy
   400                  nextState.suggestedMentions = getRoomMentionOptions(prefix, reports);
   401
   402                  // Even if there are no reports, we should show the suggestion menu - to perform live search
   403                  nextState.shouldShowSuggestionMenu = true;
   404              }
   405
   406              // Early return if there is no update
   407              const currentState = suggestionValuesRef.current;
   408              if (currentState.suggestedMentions.length === 0 && nextState.suggestedMentions?.length === 0) {
   409                  return;
   410              }
   411
   412              setSuggestionValues((prevState) => ({
   413                  ...prevState,
   414                  ...nextState,
   415              }));
   416              setHighlightedMentionIndex(0);
   417          },
   418          [isComposerFocused, isGroupPolicyReport, setHighlightedMentionIndex, resetSuggestions, getUserMentionOptions, weightedPersonalDetails, getRoomMentionOptions, reports],
   419      );
   420
   421      useEffect(() => {
   422          calculateMentionSuggestion(value, selection.start, selection.end);
   423      }, [value, selection, calculateMentionSuggestion]);
   424
   425      useEffect(() => {
   426          debouncedSearchInServer();
   427      }, [suggestionValues.suggestedMentions.length, suggestionValues.prefixType, policyID, value, debouncedSearchInServer]);
   428
   429      const updateShouldShowSuggestionMenuToFalse = useCallback(() => {
   430          setSuggestionValues((prevState) => {
   431              if (prevState.shouldShowSuggestionMenu) {
   432                  return {...prevState, shouldShowSuggestionMenu: false};
   433              }
   434              return prevState;
   435          });
   436      }, []);
   437
   438      const setShouldBlockSuggestionCalc = useCallback(
   439          (shouldBlockSuggestionCalc: boolean) => {
   440              shouldBlockCalc.current = shouldBlockSuggestionCalc;
   441          },
   442          [shouldBlockCalc],
   443      );
   444
   445      const getSuggestions = useCallback(() => suggestionValues.suggestedMentions, [suggestionValues]);
   446      const getIsSuggestionsMenuVisible = useCallback(() => isMentionSuggestionsMenuVisible, [isMentionSuggestionsMenuVisible]);
   447
   448      useImperativeHandle(
   449          ref,
   450          () => ({
   451              resetSuggestions,
   452              triggerHotkeyActions,
   453              setShouldBlockSuggestionCalc,
   454              updateShouldShowSuggestionMenuToFalse,
   455              getSuggestions,
   456              getIsSuggestionsMenuVisible,
   457          }),
   458          [resetSuggestions, setShouldBlockSuggestionCalc, triggerHotkeyActions, updateShouldShowSuggestionMenuToFalse, getSuggestions, getIsSuggestionsMenuVisible],
   459      );
   460
   461      if (!isMentionSuggestionsMenuVisible) {
   462          return null;
   463      }
   464
   465      return (
   466          <MentionSuggestions
   467              highlightedMentionIndex={highlightedMentionIndex}
   468              mentions={suggestionValues.suggestedMentions}
   469              prefix={suggestionValues.mentionPrefix}
   470              onSelect={insertSelectedMention}
   471              isMentionPickerLarge={!!isAutoSuggestionPickerLarge}
   472              measureParentContainerAndReportCursor={measureParentContainerAndReportCursor}
   473              resetSuggestions={resetSuggestions}
   474          />
   475      );
   476  }
   477
   478  SuggestionMention.displayName = 'SuggestionMention';
   479
   480  export default forwardRef(SuggestionMention);
   481
   482  export {compareUserInList};

