1  import {useIsFocused, useNavigation} from '@react-navigation/native';
     2  import lodashDebounce from 'lodash/debounce';
     3  import type {ForwardedRef, MutableRefObject, RefAttributes, RefObject} from 'react';
     4  import React, {forwardRef, memo, useCallback, useEffect, useImperativeHandle, useMemo, useRef, useState} from 'react';
     5  import type {
     6      LayoutChangeEvent,
     7      MeasureInWindowOnSuccessCallback,
     8      NativeSyntheticEvent,
     9      TextInput,
    10      TextInputFocusEventData,
    11      TextInputKeyPressEventData,
    12      TextInputScrollEventData,
    13  } from 'react-native';
    14  import {DeviceEventEmitter, findNodeHandle, InteractionManager, NativeModules, View} from 'react-native';
    15  import {useFocusedInputHandler} from 'react-native-keyboard-controller';
    16  import type {OnyxEntry} from 'react-native-onyx';
    17  import {withOnyx} from 'react-native-onyx';
    18  import {useAnimatedRef, useSharedValue} from 'react-native-reanimated';
    19  import type {Emoji} from '@assets/emojis/types';
    20  import type {FileObject} from '@components/AttachmentModal';
    21  import type {MeasureParentContainerAndCursorCallback} from '@components/AutoCompleteSuggestions/types';
    22  import Composer from '@components/Composer';
    23  import type {CustomSelectionChangeEvent, TextSelection} from '@components/Composer/types';
    24  import useKeyboardState from '@hooks/useKeyboardState';
    25  import useLocalize from '@hooks/useLocalize';
    26  import usePrevious from '@hooks/usePrevious';
    27  import useResponsiveLayout from '@hooks/useResponsiveLayout';
    28  import useStyleUtils from '@hooks/useStyleUtils';
    29  import useTheme from '@hooks/useTheme';
    30  import useThemeStyles from '@hooks/useThemeStyles';
    31  import * as Browser from '@libs/Browser';
    32  import canFocusInputOnScreenFocus from '@libs/canFocusInputOnScreenFocus';
    33  import {forceClearInput} from '@libs/ComponentUtils';
    34  import * as ComposerUtils from '@libs/ComposerUtils';
    35  import convertToLTRForComposer from '@libs/convertToLTRForComposer';
    36  import {getDraftComment} from '@libs/DraftCommentUtils';
    37  import * as EmojiUtils from '@libs/EmojiUtils';
    38  import focusComposerWithDelay from '@libs/focusComposerWithDelay';
    39  import getPlatform from '@libs/getPlatform';
    40  import * as KeyDownListener from '@libs/KeyboardShortcut/KeyDownPressListener';
    41  import Parser from '@libs/Parser';
    42  import ReportActionComposeFocusManager from '@libs/ReportActionComposeFocusManager';
    43  import * as ReportActionsUtils from '@libs/ReportActionsUtils';
    44  import * as ReportUtils from '@libs/ReportUtils';
    45  import updateMultilineInputRange from '@libs/updateMultilineInputRange';
    46  import willBlurTextInputOnTapOutsideFunc from '@libs/willBlurTextInputOnTapOutside';
    47  import getCursorPosition from '@pages/home/report/ReportActionCompose/getCursorPosition';
    48  import getScrollPosition from '@pages/home/report/ReportActionCompose/getScrollPosition';
