    12  const measureHeightOfSuggestionRows = (numRows: number, canBeBig: boolean): number => {
    13      if (canBeBig) {
    14          if (numRows > CONST.AUTO_COMPLETE_SUGGESTER.MAX_AMOUNT_OF_VISIBLE_SUGGESTIONS_IN_CONTAINER) {
