    67          const container = containerRef.current;
    68          if (!container) {
    69              return () => {};
    70          }
    71          container.onpointerdown = (e) => {
    72              if (DeviceCapabilities.hasHoverSupport()) {
    73                  return;
    74              }
    75              e.preventDefault();
    76          };
    77          return () => (container.onpointerdown = null);
    78      }, []);
