    30  function BaseAutoCompleteSuggestions<TSuggestion>(
    31      {
    32          highlightedSuggestionIndex,
    33          onSelect,
    34          accessibilityLabelExtractor,
    35          renderSuggestionMenuItem,
    36          suggestions,
    37          isSuggestionPickerLarge,
    38          keyExtractor,
    39      }: AutoCompleteSuggestionsProps<TSuggestion>,
    40      ref: ForwardedRef<View | HTMLDivElement>,
    41  ) {
    42      const styles = useThemeStyles();
    43      const StyleUtils = useStyleUtils();
    44      const rowHeight = useSharedValue(0);
    45      const scrollRef = useRef<FlashList<TSuggestion>>(null);
    46      /**
    47       * Render a suggestion menu item component.
    48       */
    49      const renderItem = useCallback(
    50          ({item, index}: RenderSuggestionMenuItemProps<TSuggestion>): ReactElement => (
    51              <PressableWithFeedback
    52                  style={({hovered}) => StyleUtils.getAutoCompleteSuggestionItemStyle(highlightedSuggestionIndex, CONST.AUTO_COMPLETE_SUGGESTER.SUGGESTION_ROW_HEIGHT, hovered, index)}
    53                  hoverDimmingValue={1}
    54                  onMouseDown={(e) => e.preventDefault()}
    55                  onPress={() => onSelect(index)}
    56                  onLongPress={() => {}}
    57                  accessibilityLabel={accessibilityLabelExtractor(item, index)}
    58              >
    59                  {renderSuggestionMenuItem(item, index)}
    60              </PressableWithFeedback>
    61          ),
    62          [accessibilityLabelExtractor, renderSuggestionMenuItem, StyleUtils, highlightedSuggestionIndex, onSelect],
    63      );
    64
    65      const innerHeight = CONST.AUTO_COMPLETE_SUGGESTER.SUGGESTION_ROW_HEIGHT * suggestions.length;
    66      const animatedStyles = useAnimatedStyle(() => StyleUtils.getAutoCompleteSuggestionContainerStyle(rowHeight.value));
    67
    68      useEffect(() => {
    69          rowHeight.value = withTiming(measureHeightOfSuggestionRows(suggestions.length, isSuggestionPickerLarge), {
    70              duration: 100,
    71              easing: Easing.inOut(Easing.ease),
    72          });
    73      }, [suggestions.length, isSuggestionPickerLarge, rowHeight]);
    74
    75      useEffect(() => {
    76          if (!scrollRef.current) {
    77              return;
    78          }
    79          scrollRef.current.scrollToIndex({index: highlightedSuggestionIndex, animated: true});
    80      }, [highlightedSuggestionIndex]);
    81
    82      return (
    83          <Animated.View
    84              ref={viewForwardedRef(ref)}
    85              style={[styles.autoCompleteSuggestionsContainer, animatedStyles]}
    86              exiting={FadeOutDown.duration(100).easing(Easing.inOut(Easing.ease))}
    87          >
    88              <ColorSchemeWrapper>
    89                  <FlashList
    90                      estimatedItemSize={CONST.AUTO_COMPLETE_SUGGESTER.SUGGESTION_ROW_HEIGHT}
    91                      ref={scrollRef}
    92                      keyboardShouldPersistTaps="handled"
    93                      data={suggestions}
    94                      renderItem={renderItem}
    95                      renderScrollComponent={ScrollView}
    96                      keyExtractor={keyExtractor}
    97                      removeClippedSubviews={false}
    98                      showsVerticalScrollIndicator={innerHeight > rowHeight.value}
    99                      extraData={highlightedSuggestionIndex}
   100                  />
   101              </ColorSchemeWrapper>
   102          </Animated.View>
   103      );
   104  }
