1  import type {ForwardedRef} from 'react';
     2  import React, {forwardRef, useCallback, useContext, useEffect, useImperativeHandle, useRef} from 'react';
     3  import type {NativeSyntheticEvent, TextInputSelectionChangeEventData} from 'react-native';
     4  import {View} from 'react-native';
     5  import type {MeasureParentContainerAndCursorCallback} from '@components/AutoCompleteSuggestions/types';
     6  import type {TextSelection} from '@components/Composer/types';
     7  import {DragAndDropContext} from '@components/DragAndDrop/Provider';
     8  import usePrevious from '@hooks/usePrevious';
     9  import type {SuggestionsRef} from './ReportActionCompose';
    10  import SuggestionEmoji from './SuggestionEmoji';
    11  import SuggestionMention from './SuggestionMention';
    12
    13  type SuggestionProps = {
    14      /** The current input value */
    15      value: string;
    16
    17      /** The current selection value */
    18      selection: TextSelection;
    19
    20      /** Callback to update the current selection */
    21      setSelection: (newSelection: TextSelection) => void;
    22
    23      /** Callback to update the comment draft */
    24      updateComment: (newComment: string, shouldDebounceSaveComment?: boolean) => void;
    25
    26      /** Measures the parent container's position and dimensions. Also add cursor coordinates */
    27      measureParentContainerAndReportCursor: (callback: MeasureParentContainerAndCursorCallback) => void;
    28
    29      /** Report composer focus state */
    30      isComposerFocused?: boolean;
    31
    32      /** Callback to reset the keyboard input */
    33      resetKeyboardInput?: () => void;
    34
    35      /** Whether the auto suggestion picker is large */
    36      isAutoSuggestionPickerLarge?: boolean;
    37
    38      /** The height of the composer */
    39      composerHeight?: number;
    40
    41      /** If current composer is connected with report from group policy */
    42      isGroupPolicyReport: boolean;
    43
    44      /** The policyID of the report connected to current composer */
    45      policyID?: string;
    46  };
    47
    48  /**
    49   * This component contains the individual suggestion components.
    50   * If you want to add a new suggestion type, add it here.
    51   *
    52   */
    53  function Suggestions(
    54      {
    55          value,
    56          selection,
    57          setSelection,
    58          updateComment,
    59          resetKeyboardInput,
    60          measureParentContainerAndReportCursor,
    61          isAutoSuggestionPickerLarge = true,
    62          isComposerFocused,
    63          isGroupPolicyReport,
    64          policyID,
    65      }: SuggestionProps,
    66      ref: ForwardedRef<SuggestionsRef>,
    67  ) {
    68      const suggestionEmojiRef = useRef<SuggestionsRef>(null);
    69      const suggestionMentionRef = useRef<SuggestionsRef>(null);
    70      const {isDraggingOver} = useContext(DragAndDropContext);
    71      const prevIsDraggingOver = usePrevious(isDraggingOver);
    72
    73      const getSuggestions = useCallback(() => {
    74          if (suggestionEmojiRef.current?.getSuggestions) {
    75              const emojiSuggestions = suggestionEmojiRef.current.getSuggestions();
    76              if (emojiSuggestions.length > 0) {
    77                  return emojiSuggestions;
    78              }
    79          }
    80
    81          if (suggestionMentionRef.current?.getSuggestions) {
    82              const mentionSuggestions = suggestionMentionRef.current.getSuggestions();
    83              if (mentionSuggestions.length > 0) {
    84                  return mentionSuggestions;
    85              }
    86          }
    87
    88          return [];
    89      }, []);
    90
    91      /**
    92       * Clean data related to EmojiSuggestions
    93       */
    94      const resetSuggestions = useCallback(() => {
    95          suggestionEmojiRef.current?.resetSuggestions();
    96          suggestionMentionRef.current?.resetSuggestions();
    97      }, []);
    98
    99      /**
   100       * Listens for keyboard shortcuts and applies the action
   101       */
   102      const triggerHotkeyActions = useCallback((e: KeyboardEvent) => {
   103          const emojiHandler = suggestionEmojiRef.current?.triggerHotkeyActions(e);
   104          const mentionHandler = suggestionMentionRef.current?.triggerHotkeyActions(e);
   105          return emojiHandler ?? mentionHandler;
   106      }, []);
   107
   108      const onSelectionChange = useCallback((e: NativeSyntheticEvent<TextInputSelectionChangeEventData>) => {
   109          const emojiHandler = suggestionEmojiRef.current?.onSelectionChange?.(e);
   110          suggestionMentionRef.current?.onSelectionChange?.(e);
   111          return emojiHandler;
   112      }, []);
   113
   114      const updateShouldShowSuggestionMenuToFalse = useCallback(() => {
   115          suggestionEmojiRef.current?.updateShouldShowSuggestionMenuToFalse();
   116          suggestionMentionRef.current?.updateShouldShowSuggestionMenuToFalse();
   117      }, []);
   118
   119      const setShouldBlockSuggestionCalc = useCallback((shouldBlock: boolean) => {
   120          suggestionEmojiRef.current?.setShouldBlockSuggestionCalc(shouldBlock);
   121          suggestionMentionRef.current?.setShouldBlockSuggestionCalc(shouldBlock);
   122      }, []);
   123      const getIsSuggestionsMenuVisible = useCallback((): boolean => {
   124          const isEmojiVisible = suggestionEmojiRef.current?.getIsSuggestionsMenuVisible() ?? false;
   125          const isSuggestionVisible = suggestionMentionRef.current?.getIsSuggestionsMenuVisible() ?? false;
   126          return isEmojiVisible || isSuggestionVisible;
   127      }, []);
   128
   129      useImperativeHandle(
   130          ref,
   131          () => ({
   132              resetSuggestions,
   133              onSelectionChange,
   134              triggerHotkeyActions,
   135              updateShouldShowSuggestionMenuToFalse,
   136              setShouldBlockSuggestionCalc,
   137              getSuggestions,
   138              getIsSuggestionsMenuVisible,
   139          }),
   140          [onSelectionChange, resetSuggestions, setShouldBlockSuggestionCalc, triggerHotkeyActions, updateShouldShowSuggestionMenuToFalse, getSuggestions, getIsSuggestionsMenuVisible],
   141      );
   142
   143      useEffect(() => {
   144          if (!(!prevIsDraggingOver && isDraggingOver)) {
   145              return;
   146          }
   147          updateShouldShowSuggestionMenuToFalse();
   148      }, [isDraggingOver, prevIsDraggingOver, updateShouldShowSuggestionMenuToFalse]);
   149
   150      const baseProps = {
   151          value,
   152          setSelection,
   153          selection,
   154          updateComment,
   155          isAutoSuggestionPickerLarge,
   156          measureParentContainerAndReportCursor,
   157          isComposerFocused,
   158          isGroupPolicyReport,
   159          policyID,
   160      };
   161
   162      return (
   163          <View testID="suggestions">
   164              <SuggestionEmoji
   165                  ref={suggestionEmojiRef}
   166                  // eslint-disable-next-line react/jsx-props-no-spreading
   167                  {...baseProps}
   168                  resetKeyboardInput={resetKeyboardInput}
   169              />
   170              <SuggestionMention
   171                  ref={suggestionMentionRef}
   172                  // eslint-disable-next-line react/jsx-props-no-spreading
   173                  {...baseProps}
   174              />
   175          </View>
   176      );
   177  }
